import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import fs from 'fs';
import path from 'path';
import { createScene } from './data/object.js';

// Build the scene
const root = createScene();

// Apply -90 degree X-rotation for Blender Z-up coordinate space.
// Three.js is Y-up; Blender is Z-up. A -90 deg rotation around X
// maps Y->-Z and Z->Y, converting to Blender's convention.
const wrapper = new THREE.Group();
wrapper.rotation.x = -Math.PI / 2;
wrapper.add(root);

// Ensure all world matrices are up to date
wrapper.updateMatrixWorld(true);

// Collect all meshes, expanding InstancedMesh into individual meshes
const exportScene = new THREE.Scene();

wrapper.traverse((obj) => {
  if (obj instanceof THREE.InstancedMesh) {
    // Expand each instance into a separate mesh with baked world transform
    const instanceMatrix = new THREE.Matrix4();
    for (let i = 0; i < obj.count; i++) {
      obj.getMatrixAt(i, instanceMatrix);

      const geom = obj.geometry.clone();
      // Instance local matrix, then the object's world matrix
      const fullMatrix = new THREE.Matrix4();
      fullMatrix.multiplyMatrices(obj.matrixWorld, instanceMatrix);

      // Check for negative determinant (mirrored scale) and flip faces if needed
      if (fullMatrix.determinant() < 0) {
        flipFaceWinding(geom);
      }

      geom.applyMatrix4(fullMatrix);
      const mesh = new THREE.Mesh(geom);
      mesh.name = (obj.name || 'instance') + '_' + i;
      exportScene.add(mesh);
    }
  } else if (obj instanceof THREE.Mesh) {
    const geom = obj.geometry.clone();

    // Check for negative determinant (mirrored scale) and flip faces if needed
    if (obj.matrixWorld.determinant() < 0) {
      flipFaceWinding(geom);
    }

    geom.applyMatrix4(obj.matrixWorld);
    const mesh = new THREE.Mesh(geom);
    mesh.name = obj.name || 'mesh';
    exportScene.add(mesh);
  }
});

function flipFaceWinding(geometry) {
  const index = geometry.getIndex();
  if (index) {
    const arr = index.array;
    for (let i = 0; i < arr.length; i += 3) {
      const tmp = arr[i + 1];
      arr[i + 1] = arr[i + 2];
      arr[i + 2] = tmp;
    }
  }
  // Flip normals
  const normal = geometry.getAttribute('normal');
  if (normal) {
    for (let i = 0; i < normal.count; i++) {
      normal.setXYZ(i, -normal.getX(i), -normal.getY(i), -normal.getZ(i));
    }
  }
}

// Export
const exporter = new OBJExporter();
const objString = exporter.parse(exportScene);

// Write output
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objString);

console.log(`OBJ exported to ${outputPath}`);
console.log(`File size: ${(fs.statSync(outputPath).size / 1024).toFixed(1)} KB`);

// Quick sanity check: count vertices and faces
const lines = objString.split('\n');
const vCount = lines.filter(l => l.startsWith('v ')).length;
const fCount = lines.filter(l => l.startsWith('f ')).length;
console.log(`Vertices: ${vCount}, Faces: ${fCount}`);

